def effective_entries(entries: list[AccessEntry]) -> list[AccessEntry]:
    """Each entry's deciding entry, in the same order.

    An MCP tool bound through the operation catalog to a REST route is a thin
    wrapper over that route (the MCP transport gate is only a floor), so the
    route's entry decides it. Every other entry decides itself.
    """
    from src.services.operation_catalog import OPERATION_CATALOG

    rest_key_by_tool = {
        op.mcp.name: (op.rest.method, op.rest.path)
        for op in OPERATION_CATALOG
        if op.mcp and op.rest
    }
    by_key = {entry.key: entry for entry in entries}
    return [
        by_key.get(rest_key_by_tool.get(entry.mcp_tool), entry) if entry.mcp_tool else entry
        for entry in entries
    ]
